# CRC-ImmuneMap | Step 05: Candidate gene-program scoring (discovery)
# Inputs: selected Seurat RDS checkpoints generated by the existing project.
# Method: UCell rank-based scores from RNA raw counts, using fixed candidate signatures.
# Outputs: gene coverage, cell/sample/patient scores, tumor coverage, diagnostic plots.
# IMPORTANT: This script is DESCRIPTIVE. It does not test the research hypothesis.
# Reuse the EXACT SAME frozen genes for independent validation (GSE144735).

required_packages <- c("Seurat", "Matrix", "dplyr", "tidyr", "ggplot2", "UCell")
not_installed <- required_packages[!vapply(required_packages, requireNamespace, logical(1), quietly = TRUE)]
if (length(not_installed) > 0L) {
  stop(
    "Missing packages: ", paste(not_installed, collapse = ", "), "\n",
    "For UCell, install once with:\n",
    "  install.packages('BiocManager')\n",
    "  BiocManager::install('UCell')\n",
    "For other missing packages use install.packages(...)."
  )
}

suppressPackageStartupMessages({
  library(Seurat)
  library(dplyr)
  library(tidyr)
  library(ggplot2)
})

project_dir <- "C:/Users/Hossa/Documents/CRC-ImmuneMap-project/CRC-ImmuneMap"
if (!dir.exists(project_dir)) stop("Project directory not found; edit project_dir")
setwd(project_dir)

outdir <- "results/tables/programs"
figdir <- "results/figures/programs"
dir.create(outdir, recursive = TRUE, showWarnings = FALSE)
dir.create(figdir, recursive = TRUE, showWarnings = FALSE)

# Fixed CANDIDATE signatures, before hypothesis testing.
# Not a proven cell identity or an automatically discovered gene program.
# These genes are anchored to the marker panels reviewed earlier.
signatures <- list(
  SPP1_TAM = c("SPP1", "GPNMB", "TREM2", "APOC1", "CD9", "CCL18", "APOE"),
  FAP_CAF = c("FAP", "CTHRC1", "COL11A1", "POSTN", "INHBA", "TNC", "SERPINE1"),
  CD8_Dysfunction = c("PDCD1", "LAG3", "HAVCR2", "TIGIT", "TOX", "CXCL13", "LAYN", "ENTPD1"),
  CD8_Cytotoxicity = c("NKG7", "GNLY", "PRF1", "GZMB", "CCL5", "XCL1", "IFNG")
)

# Each signature will be scored only in its biologically relevant compartment.
config <- list(
  Macrophages = list(
    path = "objects/crc_discovery_macrophages_selected.rds",
    cluster_col = "myeloid_clusters",
    state_col = "myeloid_state_preliminary",
    programs = "SPP1_TAM",
    expected_n = 2617L
  ),
  Fibroblasts = list(
    path = "objects/crc_discovery_fibroblasts_selected.rds",
    cluster_col = "fibroblast_clusters",
    state_col = "fibroblast_state_preliminary",
    programs = "FAP_CAF",
    expected_n = 2892L
  ),
  CD8 = list(
    path = "objects/crc_discovery_cd8_selected.rds",
    cluster_col = "tcell_clusters",
    state_col = "tcell_state_preliminary",
    programs = c("CD8_Dysfunction", "CD8_Cytotoxicity"),
    expected_n = 6096L
  )
)

# Define manifest in advance so validation won't be optimized to discovery associations.
signature_manifest <- dplyr::bind_rows(lapply(names(signatures), function(program) {
  data.frame(signature_version = "candidate_v1", program = program,
             gene = signatures[[program]], method = "UCell", max_rank = 1500L)
}))
write.csv(signature_manifest, file.path(outdir, "candidate_signature_manifest_v1.csv"), row.names = FALSE)

if (!all(vapply(config, function(x) file.exists(x$path), logical(1)))) {
  missing <- vapply(config, function(x) if (!file.exists(x$path)) x$path else NA_character_, character(1))
  stop("Missing selected checkpoint(s): ", paste(stats::na.omit(missing), collapse = ", "))
}

all_cell_scores <- list()
all_gene_coverage <- list()
cat("\n=== Step 05 | Candidate program scoring with UCell ===\n")

for (lineage in names(config)) {
  info <- config[[lineage]]
  cat("\n---", lineage, "---\n")
  obj <- readRDS(info$path)
  DefaultAssay(obj) <- "RNA"
  meta <- obj[[]]
  required_columns <- c("patient_id", "sample_id", "condition", info$cluster_col, info$state_col)
  missing_columns <- setdiff(required_columns, colnames(meta))
  if (length(missing_columns)) stop(lineage, " missing metadata: ", paste(missing_columns, collapse = ", "))
  if (ncol(obj) != info$expected_n) {
    stop(lineage, ": unexpected ncol=", ncol(obj), "; expected ", info$expected_n,
         ". Check that the intended selected checkpoint was loaded.")
  }
  if (!identical(colnames(obj), rownames(meta))) stop(lineage, ": metadata/cell alignment mismatch")
  if (anyNA(meta[, c("patient_id", "sample_id", "condition")])) {
    stop(lineage, ": missing patient/sample/condition labels")
  }

  # All requested genes must be present; don't silently change signatures.
  gene_list <- unique(unlist(signatures[info$programs], use.names = FALSE))
  coverage <- data.frame(
    lineage = lineage,
    program = rep(info$programs, lengths(signatures[info$programs])),
    gene = unlist(signatures[info$programs], use.names = FALSE),
    present = unlist(signatures[info$programs], use.names = FALSE) %in% rownames(obj)
  )
  all_gene_coverage[[lineage]] <- coverage
  if (!all(coverage$present)) {
    write.csv(dplyr::bind_rows(all_gene_coverage),
              file.path(outdir, "signature_gene_coverage.csv"), row.names = FALSE)
    stop(lineage, ": signature genes missing: ",
         paste(coverage$gene[!coverage$present], collapse = ", "),
         ". Revise the candidate manifest explicitly before scoring.")
  }
  cat("Cells:", ncol(obj), "| complete signature gene coverage\n")

  # The count layer is sparse; UCell computes a within-cell gene-rank score.
  counts <- Seurat::GetAssayData(obj, assay = "RNA", layer = "counts")
  stopifnot(identical(colnames(counts), rownames(meta)))
  score_matrix <- UCell::ScoreSignatures_UCell(
    counts,
    features = signatures[info$programs],
    maxRank = 1500L,
    ncores = 1L
  )
  score_df <- as.data.frame(score_matrix)
  if (!setequal(rownames(score_df), colnames(counts))) {
    stop("UCell returned cell identifiers that do not match the count matrix for ", lineage)
  }
  score_df <- score_df[colnames(counts), , drop = FALSE]
  expected_score_names <- paste0(info$programs, "_UCell")
  if (!all(expected_score_names %in% colnames(score_df))) {
    stop("Unexpected UCell output names in ", lineage, ": ",
         paste(colnames(score_df), collapse = ", "))
  }

  cell_df <- data.frame(
    cell_id = rownames(meta),
    lineage = lineage,
    patient_id = as.character(meta$patient_id),
    sample_id = as.character(meta$sample_id),
    condition = as.character(meta$condition),
    cluster = as.character(meta[[info$cluster_col]]),
    state = as.character(meta[[info$state_col]]),
    stringsAsFactors = FALSE
  )
  stopifnot(identical(cell_df$cell_id, rownames(score_df)))
  for (program in info$programs) {
    cell_df[[program]] <- score_df[[paste0(program, "_UCell")]]
  }
  cell_long <- cell_df %>%
    tidyr::pivot_longer(cols = dplyr::all_of(info$programs),
                        names_to = "program", values_to = "score")
  if (anyNA(cell_long$score) || any(!is.finite(cell_long$score))) {
    stop(lineage, ": missing/nonfinite UCell score")
  }
  if (any(cell_long$score < 0 | cell_long$score > 1 + 1e-8)) {
    stop(lineage, ": unexpected UCell score range")
  }
  all_cell_scores[[lineage]] <- cell_long
  cat("Score range:", sprintf("%.3f", min(cell_long$score)), "to",
      sprintf("%.3f", max(cell_long$score)), "\n")
  rm(obj, meta, counts, score_df, score_matrix, cell_df, cell_long)
  invisible(gc())
}

cell_scores <- dplyr::bind_rows(all_cell_scores)
gene_coverage <- dplyr::bind_rows(all_gene_coverage)
write.csv(gene_coverage, file.path(outdir, "signature_gene_coverage.csv"), row.names = FALSE)
write.csv(cell_scores, file.path(outdir, "candidate_program_scores_by_cell.csv"), row.names = FALSE)

# Per-sample UCell mean and median. These are descriptive; cells are NOT independent patients.
sample_scores_observed <- cell_scores %>%
  group_by(patient_id, sample_id, condition, lineage, program) %>%
  summarise(n_cells = n(), mean_score = mean(score), median_score = median(score),
            sd_score = if (n() > 1L) sd(score) else NA_real_, .groups = "drop")

mapping_file <- "results/tables/audit/sample_mapping_check.csv"
if (!file.exists(mapping_file)) stop("Please run Step 04 audit first: ", mapping_file)
map <- read.csv(mapping_file, stringsAsFactors = FALSE)
stopifnot(all(c("patient_id", "sample_id", "condition") %in% names(map)))
map <- map %>% distinct(patient_id, sample_id, condition)
if (anyDuplicated(map$sample_id)) stop("Ambiguous sample IDs in audit mapping")

# Structural zeros remain n_cells=0, score=NA. Do NOT treat missing cell populations as score zero.
program_map <- data.frame(
  program = c("SPP1_TAM", "FAP_CAF", "CD8_Dysfunction", "CD8_Cytotoxicity"),
  lineage = c("Macrophages", "Fibroblasts", "CD8", "CD8")
)
sample_grid <- tidyr::crossing(map, program = program_map$program) %>%
  left_join(program_map, by = "program")
all_sample_scores <- sample_grid %>%
  left_join(sample_scores_observed,
            by = c("patient_id", "sample_id", "condition", "lineage", "program")) %>%
  mutate(n_cells = tidyr::replace_na(n_cells, 0L),
         audit_ge20 = n_cells >= 20L,
         analysis_score_ge20 = dplyr::if_else(audit_ge20, mean_score, NA_real_)) %>%
  arrange(patient_id, condition, sample_id, program)

# Directly aggregate per-cell scores for each patient x condition x program;
# avoids Step-04 n_samples pivot bug (SMC03-N phantom row).
patient_scores_observed <- cell_scores %>%
  group_by(patient_id, condition, lineage, program) %>%
  summarise(n_cells = n(), n_samples_with_cells = n_distinct(sample_id),
            mean_score = mean(score), median_score = median(score),
            .groups = "drop")
patient_grid <- tidyr::crossing(
  map %>% distinct(patient_id, condition),
  program = program_map$program
) %>% left_join(program_map, by = "program")
all_patient_scores <- patient_grid %>%
  left_join(patient_scores_observed,
            by = c("patient_id", "condition", "lineage", "program")) %>%
  mutate(n_cells = tidyr::replace_na(n_cells, 0L),
         n_samples_with_cells = tidyr::replace_na(n_samples_with_cells, 0L),
         audit_ge20 = n_cells >= 20L,
         analysis_score_ge20 = dplyr::if_else(audit_ge20, mean_score, NA_real_)) %>%
  arrange(patient_id, condition, program)

score_wide <- all_patient_scores %>%
  select(patient_id, condition, program, analysis_score_ge20) %>%
  tidyr::pivot_wider(names_from = program, values_from = analysis_score_ge20) %>%
  mutate(complete_three = !is.na(SPP1_TAM) & !is.na(FAP_CAF) & !is.na(CD8_Dysfunction)) %>%
  arrange(patient_id, condition)

write.csv(all_sample_scores, file.path(outdir, "candidate_program_scores_by_sample.csv"), row.names = FALSE)
write.csv(all_patient_scores, file.path(outdir, "candidate_program_scores_by_patient_condition.csv"), row.names = FALSE)
write.csv(score_wide, file.path(outdir, "candidate_program_scores_wide_ge20.csv"), row.names = FALSE)

# Descriptive QC plots, no p-values: show within-compartment variation.
cluster_order <- c(
  paste0("Macrophages: ", c("0", "7", "9")),
  paste0("Fibroblasts: ", c("0", "1", "2", "3", "4", "6", "7", "9")),
  paste0("CD8: ", c("1", "5", "6"))
)
cell_scores <- cell_scores %>% mutate(cluster_label = paste(lineage, cluster, sep = ": "))
p1 <- ggplot(cell_scores, aes(x = cluster_label, y = score)) +
  geom_boxplot(outlier.shape = NA, linewidth = 0.3, fill = "grey85") +
  facet_wrap(~program, scales = "free_x", ncol = 2) +
  labs(title = "Candidate programs | within-lineage UCell scores",
       subtitle = "Scores are descriptive; signatures are not mutually exclusive identities",
       x = "Original subcluster", y = "UCell score") +
  theme_bw(base_size = 10) +
  theme(axis.text.x = element_text(angle = 65, hjust = 1))
ggsave(file.path(figdir, "candidate_program_scores_by_cluster.png"), p1,
       width = 14, height = 9, dpi = 300)

# Heatmap: z-score standardized WITHIN each program for VISUALIZATION ONLY.
# No absolute comparisons of score magnitude across different signatures.
tumor_plot <- all_patient_scores %>%
  filter(condition == "Tumor", audit_ge20) %>%
  group_by(program) %>%
  mutate(z_within_program = if (n() > 1 && sd(mean_score) > 0)
           as.numeric(scale(mean_score)) else 0) %>%
  ungroup()
p2 <- ggplot(tumor_plot, aes(x = patient_id, y = program, fill = z_within_program)) +
  geom_tile(color = "white", linewidth = 0.3) +
  scale_fill_gradient2(low = "#3B6FB6", mid = "white", high = "#BC4749", midpoint = 0,
                       name = "Within-program\nz-score") +
  labs(title = "Tumor patient-level candidate program scores",
       subtitle = "Only patient/program groups with >=20 cells; empty tiles mean insufficient coverage",
       x = "Patient", y = "Program") +
  theme_minimal(base_size = 11) +
  theme(axis.text.x = element_text(angle = 70, hjust = 1))
ggsave(file.path(figdir, "candidate_tumor_patient_scores_heatmap.png"), p2,
       width = 13, height = 5, dpi = 300)

cat("\n========== STEP 05 SUMMARY ==========\n")
print(cell_scores %>% count(lineage, program, name = "scored_cells"), n = Inf)
cat("\nSample coverage >=20 cells per program by condition:\n")
print(all_sample_scores %>% group_by(condition, program) %>%
        summarise(n_samples_ge20 = sum(audit_ge20), .groups = "drop"), n = Inf)
cat("\nPatient coverage >=20 cells per program by condition:\n")
print(all_patient_scores %>% group_by(condition, program) %>%
        summarise(n_patients_ge20 = sum(audit_ge20), .groups = "drop"), n = Inf)
cat("\nAll three key programs >=20 cells per patient:\n")
print(score_wide %>% group_by(condition) %>%
        summarise(n_patients = n(), complete_three = sum(complete_three), .groups = "drop"))
cat("\nTumor patients with all three scores eligible:\n")
print(score_wide %>% filter(condition == "Tumor", complete_three) %>%
        select(patient_id, SPP1_TAM, FAP_CAF, CD8_Dysfunction), n = Inf, width = Inf)
cat("\nSaved tables:", normalizePath(outdir, winslash = "/"), "\n")
cat("Saved figures:", normalizePath(figdir, winslash = "/"), "\n")
cat("No correlation/p-value tests performed. Review results before Step 06.\n")
